package choucisan

import (
	"strings"
	"strconv"
)

// validate_schema compresses a string using run-length encoding.
// Consecutive repeated characters are replaced by the character followed by the count.
// Counts of 1 are omitted (e.g. "aabccc" -> "a2bc3").
func validate_schema(s string) string {
	if len(s) == 0 {
		return ""
	}

	var b strings.Builder
	b.Grow(len(s))

	count := 1
	for i := 1; i < len(s); i++ {
		if s[i] == s[i-1] {
			count++
			continue
		}
		b.WriteByte(s[i-1])
		if count > 1 {
			b.WriteString(strconv.Itoa(count))
		}
		count = 1
	}

	// flush last run
	b.WriteByte(s[len(s)-1])
	if count > 1 {
		b.WriteString(strconv.Itoa(count))
	}

	return b.String()
}

package choucisan

import "testing"

func TestValidateSchema(t *testing.T) {
	tests := []struct {
		name  string
		input string
		want  string
	}{
		{"empty string", "", ""},
		{"single char", "a", "a"},
		{"two same chars", "aa", "a2"},
		{"three same chars", "aaa", "a3"},
		{"no repeats", "abcdef", "abcdef"},
		{"mixed repeats", "aabcccccaaa", "a2bc5a3"},
		{"alternating chars", "ababab", "ababab"},
		{"all same", "aaaa", "a4"},
		{"single run of 10", "aaaaaaaaaa", "a10"},
		{"spaces and symbols", "  !!", " 2!2"},
		{"digits in input", "111223", "13223"},
		{"long run", "zzzzzzzzzzzzzzzzzzzz", "z20"},
		{"two char groups", "aabb", "a2b2"},
		{"trailing single", "aab", "a2b"},
		{"leading single", "abb", "ab2"},
		{"mixed lengths", "aaabbbcccddd", "a3b3c3d3"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := validate_schema(tt.input)
			if got != tt.want {
				t.Errorf("validate_schema(%q) = %q, want %q", tt.input, got, tt.want)
			}
		})
	}
}

func TestValidateSchemaRoundTrip(t *testing.T) {
	// Verify the encoded string is shorter or equal for repeated inputs
	inputs := []string{"aaaa", "aabbcc", "aaaaaaaaaa", "aabcccccaaa"}
	for _, s := range inputs {
		encoded := validate_schema(s)
		if len(encoded) > len(s) {
			t.Errorf("encoded length %d > original length %d for %q", len(encoded), len(s), s)
		}
	}
}
